//! Bit-order golden cross-check (spec §7.2 / §13.1 / Review Focus 1 & 2).
//!
//! `golden_bitorder.json` is generated by `gen_golden.py` using cantools and is
//! the AUTHORITATIVE reference for Intel (`@1`) and Motorola (`@0`) bit order and
//! signed/factor/offset handling. If a Rust value disagrees with the golden, the
//! Rust decoder is wrong — never edit the golden to make a test pass.

use lumelog_can::dbc::{parse, ByteOrder};
use lumelog_can::decode::{extract_raw, raw_to_signed, to_physical};

struct Golden {
    message: String,
    signal: String,
    frame_hex: String,
    raw: i64,
    physical: f64,
}

const DBC: &str = include_str!("data/bitorder.dbc");
const JSON: &str = include_str!("data/golden_bitorder.json");

/// Minimal hand parse of the flat golden array (no serde — crate constraint).
fn parse_golden(json: &str) -> Vec<Golden> {
    let mut out = Vec::new();
    for chunk in json.split('{').skip(1) {
        let body = chunk.split('}').next().unwrap_or("");
        if !body.contains("\"signal\"") {
            continue; // top-level object (version/entries/note)
        }
        out.push(Golden {
            message: extract_str(body, "message"),
            signal: extract_str(body, "signal"),
            frame_hex: extract_str(body, "frame_hex"),
            raw: extract_num(body, "raw").parse::<i64>().unwrap(),
            physical: extract_num(body, "physical").parse::<f64>().unwrap(),
        });
    }
    out
}

fn extract_str(obj: &str, key: &str) -> String {
    let pat = format!("\"{key}\": \"");
    let start = obj.find(&pat).unwrap() + pat.len();
    let end = obj[start..].find('"').unwrap() + start;
    obj[start..end].to_string()
}

fn extract_num(obj: &str, key: &str) -> String {
    let pat = format!("\"{key}\": ");
    let start = obj.find(&pat).unwrap() + pat.len();
    let rest = &obj[start..];
    let end = rest.find([',', '\n', ' ']).unwrap_or(rest.len());
    rest[..end].trim().to_string()
}

fn hex_to_vec(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

#[test]
fn golden_fixture_is_present_and_nonempty() {
    assert!(JSON.contains("cantools_version"));
    assert_eq!(parse_golden(JSON).len(), 8, "4 Intel + 4 Motorola signals");
}

#[test]
fn extract_raw_and_physical_match_cantools() {
    let db = parse(DBC).expect("bitorder.dbc must parse strictly");
    let golden = parse_golden(JSON);
    assert!(!golden.is_empty());

    for g in &golden {
        let msg = db.messages.iter().find(|m| m.name == g.message).expect("message");
        let sig = msg.signals.iter().find(|s| s.name == g.signal).expect("signal");
        let data = hex_to_vec(&g.frame_hex);

        let raw_u = extract_raw(&data, sig);
        let raw_i = if sig.is_signed { raw_to_signed(raw_u, sig.length) } else { raw_u as i64 };
        assert_eq!(raw_i, g.raw, "raw mismatch for {}.{}", g.message, g.signal);

        let phys = to_physical(raw_i, sig);
        let tol = 1e-9 * g.physical.abs().max(1.0);
        assert!((phys - g.physical).abs() <= tol, "physical {} != {} for {}.{}", phys, g.physical, g.message, g.signal);
    }
}

#[test]
fn byte_orders_are_both_exercised() {
    // Guard that the fixture really covers Intel AND Motorola (else the golden
    // cross-check would be vacuous for the risky order).
    let db = parse(DBC).unwrap();
    let orders: Vec<ByteOrder> = db
        .messages
        .iter()
        .flat_map(|m| m.signals.iter().map(|s| s.byte_order))
        .collect();
    assert!(orders.contains(&ByteOrder::LittleEndian), "no Intel signals in fixture");
    assert!(orders.contains(&ByteOrder::BigEndian), "no Motorola signals in fixture");
}
